    ("critic:safety_orgs", r"""(?:future of life institute)|(?:center for ai safety)|(?:\bmiri\b)|(?:machine intelligence research institute)|(?:ai now institute)|(?:\bdair\b)|(?:stop killer robots)|(?:ai safety (institute|summit))|(?:controlai)""", ARRAY<STRING>["future of life institute", "center for ai safety", "machine intelligence research institute"]),
    ("critic:protests_backlash", r"""(?:(protest|protesta|boycott|boicot|backlash|rechazo|huelga|strike).{0,40}\b(ai|ia|artificial intelligence|inteligencia artificial)\b)|(?:(ai|ia)\b.{0,30}\b(backlash|protest|boycott))|(?:anti-ai)|(?:anti ia)|(?:luddite)|(?:ludita)|(?:no to ai)""", ARRAY<STRING>[]),
    ("critic:artists_creators", r"""(?:(artists?|artistas?|writers?|escritores?|actors?|actores?|musicians?|músicos?|authors?|autores?|actors? strike|dubbing|doblaje).{0,40}\b(ai|ia|inteligencia artificial)\b)|(?:sag-aftra)|(?:(ai|ia)\b.{0,30}\b(artists?|artistas?|creators?|creadores?))""", ARRAY<STRING>[]),
    ("critic:ai_hype_skeptics", r"""(?:ai hype)|(?:hype de la ia)|(?:overhyped)|(?:ai winter)|(?:invierno de la ia)|(?:hallucinat)|(?:alucinaci)|(?:alucinaç)|(?:(ai|llms?)\b.{0,30}\b(fail|fails|failure|limits|can.t reason|cannot reason))|(?:ai slop)|(?:basura de ia)""", ARRAY<STRING>[]),
    ("society:jobs", r"""(?:(ai|ia)\b.{0,40}\b(jobs?|layoffs?|workers?|employment|unemployment|empleos?|despidos?|trabajadores?|desempleo|empregos?|demiss|trabalhadores?))|(?:(jobs?|layoffs?|workers?|empleos?|despidos?|trabajadores?|empregos?).{0,40}\b(ai|ia|automation|automatización)\b)|(?:replaced by ai)|(?:reemplazados? por (la )?ia)|(?:substituídos? pela ia)""", ARRAY<STRING>[]),
    ("society:skills_upskilling", r"""(?:(ai|ia)\b.{0,30}\b(skills|upskill|reskill|training program|literacy|habilidades|capacitación|formación|alfabetización|competencias))|(?:(upskill|reskill|capacitación|alfabetización|literacy).{0,30}\b(ai|ia)\b)|(?:ai fluency)""", ARRAY<STRING>[]),
    ("society:leaders_executives", r"""(?:(ceo|ceos|executives?|ejecutivos?|líderes|directivos?|executivos?|board|c-suite).{0,40}\b(ai|ia|artificial intelligence|inteligencia artificial)\b)|(?:(ai|ia)\b.{0,30}\b(ceo|ceos|executives?|ejecutivos?|líderes|leadership|liderazgo))|(?:chief ai officer)""", ARRAY<STRING>[]),
    ("society:creativity_media", r"""(?:(ai|ia)\b.{0,30}\b(film|movie|hollywood|cine|película|journalism|periodismo|newsroom|music industry|industria musical|publicidad|advertising))|(?:(hollywood|newsroom|periodismo|journalism|advertising|publicidad).{0,30}\b(ai|ia)\b)|(?:ai-generated (content|film|song|ad))|(?:contenido generado por ia)""", ARRAY<STRING>[]),
    ("model:open_models", r"""(?:\bgemma ?\d)|(?:gemma-\d)|(?:\bphi-?\d)|(?:granite ?\d)|(?:ibm granite)|(?:\bolmo)|(?:\bfalcon ?\d)|(?:falcon-\d)|(?:\bjais\b)|(?:kimi k\d)|(?:gpt-oss)|(?:smollm)|(?:open-weight model)""", ARRAY<STRING>[]),
    ("model:deepseek_models", r"""(?:deepseek[- ]?(v\d|r\d|coder|math|prover|ocr))""", ARRAY<STRING>[]),
    ("model:relational_graph_fm", r"""(?:kumorfm)|(?:kumo ai)|(?:kumo\.ai)|(?:relational foundation model)|(?:graph foundation model)|(?:modelos? fundacional(es)? (relacional|de grafos))|(?:tabular foundation model)|(?:tabpfn)|(?:graph neural network)|(?:redes neuronales de grafos)""", ARRAY<STRING>[]),
    ("model:science_fm", r"""(?:(weather|climate|clima) (foundation )?model)|(?:graphcast)|(?:aurora.{0,20}\b(weather|microsoft|model))|(?:evo ?2)|(?:esm ?3)|(?:protein language model)|(?:materials? foundation model)|(?:genomic (foundation )?model)""", ARRAY<STRING>[]),
    ("research:open_initiatives", r"""(?:eleutherai)|(?:\blaion\b)|(?:ai alliance)|(?:bigscience)|(?:\bbloom\b.{0,20}\b(model|llm))|(?:open source initiative)|(?:open source ai definition)|(?:together ai)|(?:openrouter)|(?:common crawl)|(?:open datasets?)|(?:datos abiertos.{0,20}\b(ia|ai))""", ARRAY<STRING>[]),
    ("research:institutes", r"""(?:\bmila\b)|(?:vector institute)|(?:stanford (hai|crfm|ai))|(?:human-centered (ai|artificial intelligence))|(?:berkeley (ai|bair))|(?:\bbair\b)|(?:mit csail)|(?:\bcsail\b)|(?:max planck.{0,30}\b(ai|intelligent|informatics))|(?:eth z(ü|u)rich.{0,30}\b(ai|model))|(?:tsinghua.{0,30}\b(ai|model|llm))|(?:beijing academy of (ai|artificial))|(?:\bbaai\b)|(?:shanghai (ai|artificial intelligence) lab)|(?:alan turing institute)|(?:\binria\b)|(?:\bellis\b.{0,20}\b(ai|machine learning))|(?:\bcifar\b)|(?:kaist.{0,20}\b(ai|model))|(?:mbzuai)|(?:technology innovation institute)""", ARRAY<STRING>[]),
    ("lab:new_labs", r"""(?:sakana ai)|(?:reka ai)|(?:liquid ai)|(?:black forest labs)|(?:\bflux\b.{0,20}\b(image|model|1))|(?:ai21)|(?:jamba)|(?:nous research)|(?:prime intellect)|(?:reflection ai)|(?:poolside)|(?:magic\.dev)|(?:physical intelligence)|(?:skild ai)""", ARRAY<STRING>[]),
    ("lab:world_labs", r"""(?:world labs)|(?:worldlabs)|(?:spatial intelligence)|(?:inteligencia espacial)|(?:\bmarble\b.{0,20}\b(world|3d|model))""", ARRAY<STRING>[]),
    ("biz:talent_moves", r"""(?:talent war)|(?:guerra (de|por el) talento)|(?:poach)|(?:acqui-?hire)|(?:(leaves?|left|departs?|exits?|quits?|abandona|deja|sale de) (openai|anthropic|google|deepmind|meta|xai|apple|microsoft|nvidia))|(?:(joins?|hired by|ficha(do)? por|se une a|contrata(do)? por) (openai|anthropic|google|deepmind|meta|xai|microsoft|nvidia|thinking machines|safe superintelligence))|(?:(former|ex-|ex) ?(openai|anthropic|deepmind|google brain|meta ai|fair)\b.{0,40}\b(start|found|launch|raise|funda|lanza|startup|recauda))|(?:(ex|antiguos?|exempleados?|exinvestigadores?) (de )?(openai|deepmind|google|meta|anthropic))|(?:superintelligence lab.{0,30}\b(hire|recruit|ficha))|(?:(researchers?|investigadores?|engineers?|ingenieros?).{0,30}\b(leave|left|depart|exodus|éxodo|salida))""", ARRAY<STRING>[]),
    ("society:ai_for_good", r"""(?:ai for good)|(?:ia para el bien)|(?:ia para o bem)|(?:ai for (social good|humanity|climate|the planet|sustainab|development))|(?:ia (para|al servicio de) (la humanidad|el clima|el desarrollo|la sostenibilidad))|(?:humanitarian.{0,30}\b(ai|ia)\b)|(?:(ai|ia)\b.{0,30}\b(humanitarian|humanitari|sdgs?|ods|objetivos de desarrollo sostenible|sustainable development|accessibility|accesibilidad|disaster|desastres|wildfire|incendios|poverty|pobreza|agricultur|food security))|(?:itu.{0,20}\bai\b)|(?:responsible ai)|(?:ia responsable)|(?:ai ethics)|(?:ética de la ia)""", ARRAY<STRING>[]),
    ("research:prizes_competitions", r"""(?:xprize)|(?:x prize)|(?:arc prize)|(?:arc-agi)|(?:\baimo\b)|(?:ai mathematical olympiad)|(?:(imo|olimpiada (internacional )?de matemáticas).{0,30}\b(ai|ia|gold|oro|deepmind|openai))|(?:kaggle)|(?:ai cyber challenge)|(?:darpa.{0,30}\b(ai|challenge))|(?:(ai|ia)\b.{0,30}\b(prize|premio|prêmio|competition|competencia|challenge|desafío|hackathon))""", ARRAY<STRING>[])
  ])
),
hits AS (
  SELECT DISTINCT a.gkg_id, a.dt, a.lang_bucket, a.source, CONCAT('ai:', l.id) AS topic_id
  FROM `radar.article_segment` AS a
  CROSS JOIN lex AS l
  WHERE a.segment = 'ai'
    AND (
      (l.re IS NOT NULL AND REGEXP_CONTAINS(a.txt, l.re))
      OR EXISTS (SELECT 1 FROM UNNEST(a.orgs) AS o WHERE o IN UNNEST(l.orgs))
    )
),
e AS (
  SELECT DISTINCT
    gkg_id, DATE_TRUNC(dt, WEEK(MONDAY)) AS wk, lang_bucket, source, topic_id AS ent
  FROM hits
  UNION ALL
  SELECT DISTINCT gkg_id, DATE_TRUNC(dt, WEEK(MONDAY)), 'all', source, topic_id FROM hits
),
pairs AS (
  SELECT
    a.wk, a.lang_bucket, a.ent AS x, b.ent AS y, COUNT(*) AS n,
    COUNT(DISTINCT a.source) AS n_src
  FROM e AS a
  JOIN e AS b ON a.gkg_id = b.gkg_id AND a.lang_bucket = b.lang_bucket AND a.ent < b.ent
  GROUP BY a.wk, a.lang_bucket, x, y
),
deg AS (
  SELECT wk, lang_bucket, ent, COUNT(*) AS nx FROM e GROUP BY wk, lang_bucket, ent
),
tot AS (
  SELECT wk, lang_bucket, COUNT(DISTINCT gkg_id) AS n_docs FROM e GROUP BY wk, lang_bucket
)
SELECT
  p.wk, p.lang_bucket, p.x, p.y, p.n, p.n_src, d1.nx, d2.nx AS ny, t.n_docs,
  SAFE_DIVIDE(
    LN(SAFE_DIVIDE(p.n * t.n_docs, d1.nx * d2.nx)), -LN(SAFE_DIVIDE(p.n, t.n_docs))
  ) AS npmi
FROM pairs AS p
JOIN tot AS t ON t.wk = p.wk AND t.lang_bucket = p.lang_bucket
JOIN deg AS d1 ON d1.wk = p.wk AND d1.lang_bucket = p.lang_bucket AND d1.ent = p.x
JOIN deg AS d2 ON d2.wk = p.wk AND d2.lang_bucket = p.lang_bucket AND d2.ent = p.y;
